hudson.tasks.Shell.command:
#!/bin/bash set -euo pipefail
source_scripts_folder="${JENKINS_HOME}/workspace/Bash_Functions/" shopt -s nullglob for script_file in "$source_scripts_folder"*.sh; do chmod +x "$script_file" if [[ -f "$script_file" && -x "$script_file" ]]; then echo "sourcing $script_file" source "$script_file" fi done shopt -u nullglob
case "${S3_BUCKET_NAME:-}" in ""|*'$'*|*'{'*) echo "Using the controller global stack_s3_bucket: ${stack_s3_bucket:-}" ;; *) stack_s3_bucket="$S3_BUCKET_NAME" echo "Using S3_BUCKET_NAME: ${stack_s3_bucket}" ;; esac : "${stack_s3_bucket:?no bucket resolved: set S3_BUCKET_NAME or the stack_s3_bucket global}"
ENV_FILE="psama.env" validate_only="${VALIDATE_ONLY:-false}" refresh_logging_key="${REFRESH_LOGGING_KEY:-false}"
if [[ "$refresh_logging_key" == "true" ]]; then echo "REFRESH_LOGGING_KEY is true: re-uploading s3://$stack_s3_bucket/configs/psama/psama.env with the current logging key." if ! aws s3 cp "s3://$stack_s3_bucket/configs/psama/psama.env" "$ENV_FILE" --quiet; then echo "Error: could not download s3://$stack_s3_bucket/configs/psama/psama.env to refresh it; refusing to upload." >&2 exit 1 fi fi
if [[ ! -f "$ENV_FILE" || ! -s "$ENV_FILE" ]]; then echo "Error: $ENV_FILE is missing or empty; refusing to upload." >&2 exit 1 fi
definition_count() { grep -c "^${1}=" "$ENV_FILE" || true }
definition_value() { sed -n "s/^${1}=//p" "$ENV_FILE" }
value_shape() { printf '%s\n' "$1" | LC_ALL=C sed -e 's/[A-Za-z]/a/g' -e 's/[0-9]/9/g' -e 's/[^a9]/./g' }
# The pattern requires a non-whitespace character after the =. A key set to a single space # reads as configured to a plain presence test and as blank to PSAMA. require_single_non_empty() { local key=$1 if [[ "$(definition_count "$key")" -ne 1 ]] || ! grep -q "^${key}=[[:space:]]*[^[:space:]]" "$ENV_FILE"; then return 1 fi return 0 }
require_canonical_boolean() { local key=$1 local count count=$(definition_count "$key") if [[ "$count" -gt 1 ]]; then echo "Error: $ENV_FILE defines $key more than once; refusing to upload." >&2 exit 1 fi if [[ "$count" -eq 0 ]]; then return 0 fi local value value=$(definition_value "$key") if [[ "$value" != "true" && "$value" != "false" ]]; then echo "Error: $key must be exactly true or false; the uploaded value has length ${#value} and shape $(value_shape "$value"). Refusing to upload." >&2 echo "Spring also reads yes, on and 1 as true, so a non-canonical value silently flips this flag." >&2 exit 1 fi return 0 }
provider_is_enabled() { [[ "$(definition_value "$1")" == "true" ]] }
required_keys=( APPLICATION_CLIENT_SECRET APPLICATION_CLIENT_SECRET_IS_BASE_64 DATASOURCE_URL DATASOURCE_USERNAME STRICT_AUTHORIZATION_APPLICATIONS ENABLE_PUBLIC_ACCESS CONSENT_BASED_AUTHORIZATION_ENABLED TOS_ENABLED USER_ID_CLAIM TOKEN_INCLUSION_ROLES TOKEN_EXPIRATION_TIME MAX_SESSION_TIME LONG_TERM_TOKEN_EXPIRATION_TIME SERVER_PORT ) for key in "${required_keys[@]}"; do if ! require_single_non_empty "$key"; then echo "Error: $ENV_FILE must define exactly one non-empty $key value; refusing to upload." >&2 if [[ "$key" == "STRICT_AUTHORIZATION_APPLICATIONS" ]]; then echo "An empty value makes no connection strict, and an empty merged access-rule set then grants rather than denies." >&2 fi exit 1 fi done
for key in ENABLE_PUBLIC_ACCESS TOS_ENABLED CONSENT_BASED_AUTHORIZATION_ENABLED APPLICATION_CLIENT_SECRET_IS_BASE_64; do require_canonical_boolean "$key" done
# A non-canonical flag here would enable a provider in Spring while this check skipped that # provider's keys. An absent flag stays legal and means the provider is off. for key in OPEN_IDP_PROVIDER_IS_ENABLED A4_OKTA_IDP_PROVIDER_IS_ENABLED FENCE_IDP_PROVIDER_IS_ENABLED AUTH0_IDP_PROVIDER_IS_ENABLED RAS_OKTA_IDP_PROVIDER_IS_ENABLED; do require_canonical_boolean "$key" done
# An identity provider's credentials are required only while its flag is true. Okta, Fence # and RAS issue those secrets, so this check can only ever verify presence. idp_requirements=( "A4_OKTA_IDP_PROVIDER_IS_ENABLED A4_OKTA_CLIENT_ID A4_OKTA_CLIENT_SECRET A4_OKTA_CONNECTION_ID A4_OKTA_IDP_PROVIDER_URI" "FENCE_IDP_PROVIDER_IS_ENABLED FENCE_CLIENT_ID FENCE_CLIENT_SECRET FENCE_IDP_PROVIDER_URI" "RAS_OKTA_IDP_PROVIDER_IS_ENABLED RAS_OKTA_CLIENT_ID RAS_OKTA_CLIENT_SECRET RAS_OKTA_CONNECTION_ID RAS_OKTA_IDP_PROVIDER_URI RAS_IDP_URI RAS_PASSPORT_ISSUER" "AUTH0_IDP_PROVIDER_IS_ENABLED AUTH0_HOST" ) for requirement in "${idp_requirements[@]}"; do read -r provider_flag dependent_keys <<< "$requirement" if ! provider_is_enabled "$provider_flag"; then continue fi for key in $dependent_keys; do if ! require_single_non_empty "$key"; then echo "Error: $provider_flag is true, so $ENV_FILE must define exactly one non-empty $key value; refusing to upload." >&2 exit 1 fi done done
# Notification mail has no enable flag, so the pair itself is the switch. mail_keys_set=0 for key in EMAIL_ADDRESS EMAIL_PASSWORD; do if [[ "$(definition_count "$key")" -gt 1 ]]; then echo "Error: $ENV_FILE defines $key more than once; refusing to upload." >&2 exit 1 fi if grep -q "^${key}=[[:space:]]*[^[:space:]]" "$ENV_FILE"; then mail_keys_set=$((mail_keys_set + 1)) fi done if [[ "$mail_keys_set" -eq 1 ]]; then echo "Error: EMAIL_ADDRESS and EMAIL_PASSWORD are a pair; set both to enable notification mail or leave both empty; refusing to upload." >&2 exit 1 fi
if [[ "$validate_only" == "true" ]]; then echo "$ENV_FILE passed every PSAMA required-key rule." echo "VALIDATE_ONLY is true, so nothing was uploaded and s3://$stack_s3_bucket/configs/psama/psama.env is unchanged." exit 0 fi
shared_logging_env=$(mktemp) if ! aws s3 cp "s3://$stack_s3_bucket/configs/pic-sure-logging/logging.env" "$shared_logging_env" --quiet; then rm -f "$shared_logging_env" echo "Error: could not read s3://$stack_s3_bucket/configs/pic-sure-logging/logging.env, so PSAMA would start without the audit logging key; refusing to upload." >&2 echo "Run 'Render PIC-SURE Configuration' with RENDER_LOGGING to write it, then re-run this job." >&2 exit 1 fi logging_api_key=$(sed -n 's/^LOGGING_API_KEY=//p' "$shared_logging_env" | head -n 1) rm -f "$shared_logging_env" if [[ -z "$logging_api_key" ]]; then echo "Error: s3://$stack_s3_bucket/configs/pic-sure-logging/logging.env has no non-empty LOGGING_API_KEY; refusing to upload." >&2 exit 1 fi grep -v -e '^LOGGING_API_KEY=' -e '^LOGGING_SERVICE_URL=' "$ENV_FILE" > "$ENV_FILE.with-logging" || true printf 'LOGGING_SERVICE_URL=http://pic-sure-logging\nLOGGING_API_KEY=%s\n' "$logging_api_key" >> "$ENV_FILE.with-logging" mv "$ENV_FILE.with-logging" "$ENV_FILE"
echo "Validated $ENV_FILE against the PSAMA required-key rules and set its audit logging key; uploading." aws s3 --sse=AES256 cp "$ENV_FILE" "s3://$stack_s3_bucket/configs/psama/psama.env"
